def transform(grid):
    """Copy the marked shape to every all-zero location where it fits."""
    rows, cols = len(grid), len(grid[0])
    counts = {v: sum(row.count(v) for row in grid) for row in grid for v in set(row)}
    color = min((v for v in counts if v != 0), key=lambda v: counts[v])
    marked = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == color]
    if not marked:
        return [row[:] for row in grid]
    top = min(r for r, _ in marked)
    left = min(c for _, c in marked)
    shape = [(r - top, c - left) for r, c in marked]
    height = max(r for r, _ in shape) + 1
    width = max(c for _, c in shape) + 1
    out = [row[:] for row in grid]
    for r in range(rows - height + 1):
        for c in range(cols - width + 1):
            cells = [(r + dr, c + dc) for dr, dc in shape]
            if all(grid[rr][cc] == 0 for rr, cc in cells):
                for rr, cc in cells:
                    out[rr][cc] = color
    return out

